using Mutagen.Bethesda;
using Mutagen.Bethesda.Synthesis;
using Mutagen.Bethesda.Skyrim;
using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Cache;
using Noggog;
using System;
using System.Linq;
using System.ComponentModel.DataAnnotations;
using System.Xml;
using System.Diagnostics;

namespace RandomSpellMerchantPatcher
{
    public class Program
    {
        private static Lazy<Settings> Settings = null!;
        public static async Task<int> Main(string[] args)
        {
            return await SynthesisPipeline.Instance
                .AddPatch<ISkyrimMod, ISkyrimModGetter>(RunPatch)
                .SetAutogeneratedSettings(
                    nickname: "RSM Settings",
                    path: "settings.json",
                    out Settings)
                .SetTypicalOpen(GameRelease.SkyrimSE, "RandomSpellMerchant.esp")
                .Run(args);
        }

        public static void RunPatch(IPatcherState<ISkyrimMod, ISkyrimModGetter> state)
        {

            // Read the user-configurable rarity and roll settings.
            // Higher no-tome chances make that rarity less likely to appear.

            int commonChanceNone = Settings.Value.CommonChanceNone;
            int rareChanceNone = Settings.Value.RareChanceNone;
            int veryRareChanceNone = Settings.Value.VeryRareChanceNone;

            // Multiplies the base number of rolls. Higher values add more tomes to merchant inventories.

            int numOfRollMag = Settings.Value.RollMag;

            // Reduces rolls for higher spell tiers. This value must be at least 1.

            int lvlMult = Settings.Value.TierRollReduction;

            // Enables or disables the spell-skill requirements on generated leveled lists.

            bool isSpellLvl = Settings.Value.IsSpellLvl;

