                ("25 Illusion Rare", illusion25RareRolls, rareChanceNone, 1),
                ("25 Illusion Very Rare", illusion25VeryRareRolls, veryRareChanceNone, 1),
                ("50 Illusion Common", illusion50CommonRolls, commonChanceNone, 1),
                ("50 Illusion Rare", illusion50RareRolls, rareChanceNone, 1),
                ("50 Illusion Very Rare", illusion50VeryRareRolls, veryRareChanceNone, 1),
                ("75 Illusion Common", illusion75CommonRolls, commonChanceNone, 1),
                ("75 Illusion Rare", illusion75RareRolls, rareChanceNone, 1),
                ("75 Illusion Very Rare", illusion75VeryRareRolls, veryRareChanceNone, 1),
                ("100 Illusion Common", illusion100CommonRolls, commonChanceNone, 1),
                ("100 Illusion Rare", illusion100RareRolls, rareChanceNone, 1),
                ("100 Illusion Very Rare", illusion100VeryRareRolls, veryRareChanceNone, 1));

            PrintAverageInventory(
                "Restoration specialist list (one copy):",
                ("00 Restoration Common", restoration00CommonRolls, commonChanceNone, 1),
                ("00 Restoration Rare", restoration00RareRolls, rareChanceNone, 1),
                ("00 Restoration Very Rare", restoration00VeryRareRolls, veryRareChanceNone, 1),
                ("25 Restoration Common", restoration25CommonRolls, commonChanceNone, 1),
                ("25 Restoration Rare", restoration25RareRolls, rareChanceNone, 1),
                ("25 Restoration Very Rare", restoration25VeryRareRolls, veryRareChanceNone, 1),
                ("50 Restoration Common", restoration50CommonRolls, commonChanceNone, 1),
                ("50 Restoration Rare", restoration50RareRolls, rareChanceNone, 1),
                ("50 Restoration Very Rare", restoration50VeryRareRolls, veryRareChanceNone, 1),
                ("75 Restoration Common", restoration75CommonRolls, commonChanceNone, 1),
                ("75 Restoration Rare", restoration75RareRolls, rareChanceNone, 1),
                ("75 Restoration Very Rare", restoration75VeryRareRolls, veryRareChanceNone, 1),
                ("100 Restoration Common", restoration100CommonRolls, commonChanceNone, 1),
                ("100 Restoration Rare", restoration100RareRolls, rareChanceNone, 1),
                ("100 Restoration Very Rare", restoration100VeryRareRolls, veryRareChanceNone, 1));
        }


        // Helper methods.

        private static LeveledItem CreateParentList(IPatcherState<ISkyrimMod, ISkyrimModGetter> state, string editorId)
        {
            var list = state.PatchMod.LeveledItems.AddNew();
            list.EditorID = editorId;
            list.Entries = new ExtendedList<LeveledItemEntry>();
            SetUseAll(list, true);
            return list;
        }

        private static ILeveledItemGetter? FindLeveledItemByEditorID(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state,
            string editorId)
        {
            return state.LoadOrder.PriorityOrder.LeveledItem().WinningOverrides()
                .FirstOrDefault(x =>
                    x.EditorID != null &&
                    x.EditorID.Equals(editorId, StringComparison.OrdinalIgnoreCase));
        }

        private static void SetUseAll(LeveledItem list, bool enabled)
        {
            if (enabled)
            {
                list.Flags |= LeveledItem.Flag.UseAll;
            }
            else
            {
                list.Flags &= ~LeveledItem.Flag.UseAll;
            }
        }

        private static void SetChanceNone(LeveledItem list, int percent)
        {
            percent = Math.Clamp(percent, 0, 100);
            list.ChanceNone = new Percent(percent / 100.0);
        }

        private static IBookGetter? FindBookByEditorID(IPatcherState<ISkyrimMod, ISkyrimModGetter> state, string editorId)
        {
            return state.LoadOrder.PriorityOrder.Book().WinningOverrides()
                .FirstOrDefault(x =>
                    x.EditorID != null &&
                    x.EditorID.Equals(editorId, StringComparison.OrdinalIgnoreCase));
        }

        private static void SetSkillGate(LeveledItem list, IPatcherState<ISkyrimMod, ISkyrimModGetter> state, string globalEditorId)
        {
            var globalGetter = state.LoadOrder.PriorityOrder.Global().WinningOverrides()
                .FirstOrDefault(x =>
                    x.EditorID != null &&
                    x.EditorID.Equals(globalEditorId, StringComparison.OrdinalIgnoreCase));

            if (globalGetter == null)
            {
                Console.WriteLine($"WARNING: Could not find global: {globalEditorId}");
                return;
            }

            list.Global = globalGetter.ToNullableLink();
        }

        private static bool IsAnyPluginLoaded(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state,
            params string[] pluginNames)
        {
            foreach (var pluginName in pluginNames)
            {
                if (string.IsNullOrWhiteSpace(pluginName))
                {
                    continue;
                }

                if (state.LoadOrder.PriorityOrder.Any(x =>
                    x.ModKey.ToString().Equals(pluginName, StringComparison.OrdinalIgnoreCase)))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsAnyCreationClubPluginLoaded(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state)
        {
            // AE / Creation Club plugins are separate ESL/ESM files and normally start with "cc".
            // This catches them without needing to manually maintain every CC plugin filename above.
            return state.LoadOrder.PriorityOrder.Any(x =>
                x.ModKey.ToString().StartsWith("cc", StringComparison.OrdinalIgnoreCase));
        }


        private static string[] UseIfLoaded(bool pluginEnabled, string[] editorIDs)
        {
            return pluginEnabled ? editorIDs : Array.Empty<string>();
        }

        private static string[] Combine(params string[][] arrays)
        {
            return arrays
                .Where(x => x != null)
                .SelectMany(x => x)
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
        }

        private static LeveledItem CreateSpellTomeList(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state,
            string newEditorId,
            string[] spellTomeEditorIDs,
            int chanceNone,
            bool isSpellLvl,
            string? skillGateGlobalEditorId = null)
        {
            var list = state.PatchMod.LeveledItems.AddNew();
            list.EditorID = newEditorId;
            list.Entries = new ExtendedList<LeveledItemEntry>();

            SetUseAll(list, false);
            SetChanceNone(list, chanceNone);

            if (isSpellLvl == true)
            {
                if (skillGateGlobalEditorId != null)
                {
                    SetSkillGate(list, state, skillGateGlobalEditorId);
                }
            }

            foreach (var editorId in spellTomeEditorIDs)
            {
                var bookGetter = FindBookByEditorID(state, editorId);

                if (bookGetter == null)
                {
                    Console.WriteLine($"Skipping: {editorId}");
                    continue;
                }

                list.Entries.Add(new LeveledItemEntry()
                {
                    Data = new LeveledItemEntryData()
                    {
                        Level = 1,
                        Count = 1,
                        Reference = bookGetter.ToLink()
                    }
                });
            }


            return list;
        }


        private static void AddListRolls(LeveledItem parentList, LeveledItem childList, int count)
        {
            parentList.Entries ??= new ExtendedList<LeveledItemEntry>();

            for (int i = 0; i < count; i++)
            {
                parentList.Entries.Add(new LeveledItemEntry()
                {
                    Data = new LeveledItemEntryData()
                    {
                        Level = 1,
                        Count = 1,
                        Reference = childList.ToLink()
                    }
                });
            }
        }

