        private static void AddContainerListRolls(Container container, LeveledItem list, int count)
        {
            container.Items ??= new ExtendedList<ContainerEntry>();

            for (int i = 0; i < count; i++)
            {
                container.Items.Add(new ContainerEntry()
                {
                    Item = new ContainerItem()
                    {
                        Count = 1,
                        Item = list.ToLink()
                    }
                });
            }
        }

        private static void AddSpecialtyToCollegeSellers(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state,
            string[] collegeSellerEditorIDs,
            LeveledItem specialistList,
            int specialtyCopies,
            LeveledItem expertList)
        {
            foreach (var editorId in collegeSellerEditorIDs)
            {
                var chestGetter = state.LoadOrder.PriorityOrder.Container().WinningOverrides()
                    .FirstOrDefault(x => string.Equals(x.EditorID, editorId, StringComparison.OrdinalIgnoreCase));

                if (chestGetter == null)
                {
                    Console.WriteLine($"WARNING: Could not find College seller chest: {editorId}");
                    continue;
                }

                var chest = state.PatchMod.Containers.GetOrAddAsOverride(chestGetter);
                chest.Items ??= new ExtendedList<ContainerEntry>();

                RemoveExistingSpellTomeLists(state, chest, editorId);
                AddContainerListRolls(chest, specialistList, specialtyCopies);

                if (specialistList.EditorID?.Contains("Alteration") == true)
                {
                    AddContainerListRolls(chest, expertList, specialtyCopies);

                }
                if (specialistList.EditorID?.Contains("Conjuration") == true)
                {
                    AddContainerListRolls(chest, expertList, specialtyCopies);

                }
                if (specialistList.EditorID?.Contains("Destruction") == true)
                {
                    AddContainerListRolls(chest, expertList, specialtyCopies);

                }
                if (specialistList.EditorID?.Contains("Illusion") == true)
                {
                    AddContainerListRolls(chest, expertList, specialtyCopies);

                }
                if (specialistList.EditorID?.Contains("Restoration") == true)
                {
                    AddContainerListRolls(chest, expertList, specialtyCopies);

                }
            }
        }

        private static void RemoveExistingSpellTomeLists(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state,
            Container chest,
            string chestEditorId)
        {
            chest.Items ??= new ExtendedList<ContainerEntry>();

            for (int i = chest.Items.Count - 1; i >= 0; i--)
            {
                var entry = chest.Items[i];

                if (entry.Item.Item.TryResolve<ILeveledItemGetter>(state.LinkCache, out var list))
                {
                    if (list.EditorID != null && list.EditorID.Contains("TVR", StringComparison.OrdinalIgnoreCase))
                    {
                        chest.Items.RemoveAt(i);
                        continue;
                    }  
                    if (list.EditorID != null && list.EditorID.Contains("CCLItemSpell", StringComparison.OrdinalIgnoreCase))
                    {
                        chest.Items.RemoveAt(i);
                        continue;
                    }
                    if (list.EditorID != null && list.EditorID.Contains("SpellTome", StringComparison.OrdinalIgnoreCase))
                    {
                        chest.Items.RemoveAt(i);
                    }
                }
            }
        }

       private static int NumberOfRollGetter(
            LeveledItem list,
            int lvlMult,
            int totalRollMag)
        {
            int count = list.Entries?.Count ?? 0;

            if (count == 0)
            {
                return 0;
            }

            double numberOfRoll = count / 2.0;

            if (list.EditorID?.Contains("Common") == true)
            {
                numberOfRoll *= totalRollMag;
            }
            else if (list.EditorID?.Contains("VeryRare") == true)
            {
                numberOfRoll = numberOfRoll / 3.0 * totalRollMag;
            }
            else if (list.EditorID?.Contains("Rare") == true)
            {
                numberOfRoll = numberOfRoll / 2.0 * totalRollMag;
            }

            if (list.EditorID?.Contains("25") == true)
            {
                numberOfRoll /= lvlMult;
            }
            else if (list.EditorID?.Contains("50") == true)
            {
                numberOfRoll /= lvlMult * 2.0;
            }
            else if (list.EditorID?.Contains("75") == true)
            {
                numberOfRoll /= lvlMult * 3.0;
            }
            else if (list.EditorID?.Contains("100") == true)
            {
                numberOfRoll /= lvlMult * 4.0;
            }

            int roundedRolls = (int)Math.Floor(numberOfRoll);

            return Math.Max(1, roundedRolls);
        }

        private static void PrintAverageInventory(
            string merchantGroup,
            params (string Label, int Rolls, int ChanceNone, int Copies)[] entries)
        {
            Console.WriteLine(merchantGroup);

            foreach (var entry in entries)
            {
                double averageBooks =
                    entry.Rolls *
                    entry.Copies *
                    ((100.0 - entry.ChanceNone) / 100.0);

                Console.WriteLine(
                    $"{entry.Label} will have {averageBooks:0.00} books on average.");
            }
        }

        private static void RemoveOrReplaceExistingSpellTomeLists(
            IPatcherState<ISkyrimMod, ISkyrimModGetter> state,
            Container chest,
            string chestEditorId,
            LeveledItem destructionSpecialist,
            LeveledItem alterationSpecialist,
            LeveledItem conjurationSpecialist,
            LeveledItem illusionSpecialist,
            LeveledItem restorationSpecialist)
        {
            bool addDestructionSpecialist = false;
            bool addAlterationSpecialist = false;
            bool addConjurationSpecialist = false;
            bool addIllusionSpecialist = false;
            bool addRestorationSpecialist = false;

            chest.Items ??= new ExtendedList<ContainerEntry>();


            for (int i = chest.Items.Count - 1; i >= 0; i--)
            {
                var entry = chest.Items[i];
                if (entry.Item.Item.TryResolve<ILeveledItemGetter>(state.LinkCache, out var list))
                {
                    if (list.EditorID != null && list.EditorID.Contains("TVR", StringComparison.OrdinalIgnoreCase))
                    {
                        chest.Items.RemoveAt(i);
                        continue;
                    } 
                    
                    if (list.EditorID != null && list.EditorID.Contains("SpellTome", StringComparison.OrdinalIgnoreCase))
                    {
                        if (list.EditorID.Contains("Destruction", StringComparison.OrdinalIgnoreCase))
                        {
                            if (!addDestructionSpecialist)
                            {
                                addDestructionSpecialist = true;
                                entry.Item.Item = destructionSpecialist.ToLink();
                            }
                            else
                            {
                                chest.Items.RemoveAt(i);
                            }
                        }
                        else if (list.EditorID.Contains("Alteration", StringComparison.OrdinalIgnoreCase))
                        {
                            if (!addAlterationSpecialist)
                            {
                                addAlterationSpecialist = true;
                                entry.Item.Item = alterationSpecialist.ToLink();
                            }
                            else
                            {
                                chest.Items.RemoveAt(i);
                            }
                        }
                        else if (list.EditorID.Contains("Conjuration", StringComparison.OrdinalIgnoreCase))
                        {
                            if (!addConjurationSpecialist)
                            {
                                addConjurationSpecialist = true;
                                entry.Item.Item = conjurationSpecialist.ToLink();
                            }
                            else
                            {
                                chest.Items.RemoveAt(i);
                            }
                        }
                        else if (list.EditorID.Contains("Illusion", StringComparison.OrdinalIgnoreCase))
                        {
                            if (!addIllusionSpecialist)
                            {
                                addIllusionSpecialist = true;
                                entry.Item.Item = illusionSpecialist.ToLink();
                            }
                            else
                            {
                                chest.Items.RemoveAt(i);
                            }
                        }
                        else if (list.EditorID.Contains("Restoration", StringComparison.OrdinalIgnoreCase))
                        {
                            if (!addRestorationSpecialist)
                            {
                                addRestorationSpecialist = true;
                                entry.Item.Item = restorationSpecialist.ToLink();
                            }
                            else
                            {
                                chest.Items.RemoveAt(i);
                            }
                        }
                        else
                        {
                            chest.Items.RemoveAt(i);
                        }
                    }
                }
            }
        }
    }
